const NATIONAL_PARKS=[["Acadia", "Maine"], ["Arches", "Utah"], ["Badlands", "South Dakota"], ["Big Bend", "Texas"], ["Biscayne", "Florida"], ["Black Canyon of the Gunnison", "Colorado"], ["Bryce Canyon", "Utah"], ["Canyonlands", "Utah"], ["Capitol Reef", "Utah"], ["Carlsbad Caverns", "New Mexico"], ["Channel Islands", "California"], ["Congaree", "South Carolina"], ["Crater Lake", "Oregon"], ["Cuyahoga Valley", "Ohio"], ["Death Valley", "California and Nevada"], ["Denali", "Alaska"], ["Dry Tortugas", "Florida"], ["Everglades", "Florida"], ["Gates of the Arctic", "Alaska"], ["Gateway Arch", "Missouri and Illinois"], ["Glacier Bay", "Alaska"], ["Glacier", "Montana"], ["Grand Canyon", "Arizona"], ["Grand Teton", "Wyoming"], ["Great Basin", "Nevada"], ["Great Sand Dunes", "Colorado"], ["Great Smoky Mountains", "North Carolina and Tennessee"], ["Guadalupe Mountains", "Texas"], ["Haleakalā", "Hawaii"], ["Hawai'i Volcanoes", "Hawaii"], ["Hot Springs", "Arkansas"], ["Indiana Dunes", "Indiana"], ["Isle Royale", "Michigan"], ["Joshua Tree", "California"], ["Katmai", "Alaska"], ["Kenai Fjords", "Alaska"], ["Kings Canyon", "California"], ["Kobuk Valley", "Alaska"], ["Lake Clark", "Alaska"], ["Lassen Volcanic", "California"], ["Mammoth Cave", "Kentucky"], ["Mesa Verde", "Colorado"], ["Mount Rainier", "Washington"], ["National Park of American Samoa", "American Samoa"], ["New River Gorge", "West Virginia"], ["North Cascades", "Washington"], ["Olympic", "Washington"], ["Petrified Forest", "Arizona"], ["Pinnacles", "California"], ["Redwood", "California"], ["Rocky Mountain", "Colorado"], ["Saguaro", "Arizona"], ["Sequoia", "California"], ["Shenandoah", "Virginia"], ["Theodore Roosevelt", "North Dakota"], ["Virgin Islands", "U.S. Virgin Islands"], ["Voyageurs", "Minnesota"], ["White Sands", "New Mexico"], ["Wind Cave", "South Dakota"], ["Wrangell-St. Elias", "Alaska"], ["Yellowstone", "Idaho, Montana, and Wyoming"], ["Yosemite", "California"], ["Zion", "Utah"]];
