let data=loadData(),activeListId=null,activeEntryId=null,activeSlide=0,activePhotoIndex=0,photoTimer=null,cardPhotoTimer=null,homePhotoTimer=null,cardPhotoIndices=new Map(),homePhotoIndices=new Map(),searchTimer=null;
function loadData(){if(window.__LITTLE_LIST_SHARED__?.lists)return structuredClone(window.__LITTLE_LIST_SHARED__);try{const s=JSON.parse(localStorage.getItem(STORAGE_KEY));if(s&&Array.isArray(s.lists))return s}catch(e){}return{lists:structuredClone(initialLists)}}
function save(){const dot=document.querySelector('.sync-dot');let localSaved=true;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data))}catch{localSaved=false}const session=getSession()||window.__LITTLE_LIST_SESSION__;if(session?.access_token)return saveSharedState(session.access_token,data).then(()=>{dot?.classList.remove('sync-error');dot?.classList.add('saved');return true}).catch(()=>{dot?.classList.add('sync-error');return false});if(!localSaved)dot?.classList.add('sync-error');return Promise.resolve(localSaved)}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function duplicateTitle(l,title,excludeId=null){const normalized=String(title||'').trim().toLocaleLowerCase('en').replace(/\s+/g,' ');return l.entries.some(entry=>entry.id!==excludeId&&String(entry.title||'').trim().toLocaleLowerCase('en').replace(/\s+/g,' ')===normalized)}
function dedupeMovieTitles(l){if(l.kind!=='movies')return false;const byTitle=new Map(),unique=[];let changed=false;for(const entry of l.entries){const key=String(entry.title||'').trim().toLocaleLowerCase('en').replace(/\s+/g,' '),existing=byTitle.get(key);if(!key||!existing){if(key)byTitle.set(key,entry);unique.push(entry);continue}changed=true;existing.watched=Boolean(existing.watched||entry.watched);existing.category=existing.category||entry.category||'';existing.date=existing.date||entry.date||'';existing.poster=existing.poster||entry.poster||'';existing.releaseYear=existing.releaseYear||entry.releaseYear||'';existing.reviews=existing.reviews||entry.reviews||{};for(const person of ['you','chris']){const oldReview=existing.reviews[person],newReview=entry.reviews?.[person];if((!oldReview?.text&&!oldReview?.stars)&&newReview)existing.reviews[person]=newReview}existing.photos=[...new Set([...(existing.photos||[]),...(entry.photos||[])])];if(!Number.isFinite(existing.watchOrder)||Number.isFinite(entry.watchOrder)&&entry.watchOrder<existing.watchOrder)existing.watchOrder=entry.watchOrder}if(changed)l.entries=unique;return changed}

function listById(id){return data.lists.find(x=>x.id===id)}function entryById(){return listById(activeListId)?.entries.find(e=>e.id===activeEntryId)}
function setRoute(listId=null,entryId=null){if(listId!==activeListId&&listById(listId)?.kind==='movies')activeMovieCategory='';if(photoTimer){clearInterval(photoTimer);photoTimer=null}if(cardPhotoTimer){clearInterval(cardPhotoTimer);cardPhotoTimer=null}if(homePhotoTimer){clearInterval(homePhotoTimer);homePhotoTimer=null}activeListId=listId;activeEntryId=entryId;activePhotoIndex=0;render()}
function render(){const movieListIndex=data.lists.findIndex(list=>list.kind==='movies');if(movieListIndex>0)data.lists.unshift(data.lists.splice(movieListIndex,1)[0]);document.querySelectorAll('.view').forEach(v=>v.classList.add('hidden'));const navMarkup=data.lists.map(l=>`<button class="side-link ${l.id===activeListId?'active':''}" data-list="${escapeHtml(l.id)}"><span class="nav-icon">${l.icon}</span>${escapeHtml(l.name)}</button>`).join('');const nav=document.getElementById('sideNav');nav.innerHTML=navMarkup;const mobileNav=document.getElementById('mobileNav');mobileNav.innerHTML=navMarkup;[nav,mobileNav].forEach(container=>container.querySelectorAll('[data-list]').forEach(b=>b.onclick=()=>setRoute(b.dataset.list)));const crumb=document.getElementById('crumbCurrent');if(activeEntryId){const l=listById(activeListId);if(crumb)crumb.textContent=(l?.name+' / '+entryById()?.title).toUpperCase();renderDetail()}else if(activeListId){if(crumb)crumb.textContent=(listById(activeListId)?.name||'LIST').toUpperCase();renderList()}else{if(crumb)crumb.textContent='ALL LISTS';renderHome()}}
function listPhotos(list){return list.entries.flatMap(entry=>{const posters=list.kind==='movies'&&entry.poster?[{src:entry.poster,poster:true}]:[];const photos=(entry.photos||[]).map((src,index)=>({src,position:entry.photoPositions?.[index]||{x:50,y:50}}));return [...posters,...photos]})}
function renderHome(){const parks=listById('parks');if(parks)seedNationalParks(parks);if(homePhotoTimer){clearInterval(homePhotoTimer);homePhotoTimer=null}const el=document.getElementById('homeView');el.classList.remove('hidden');el.innerHTML=`<div class="home-heading"><div class="home-title"><h1 class="page-title">Our lists, <em>our lives</em></h1><p class="subhead">All the things we want to remember, explore, and do together.</p></div><div class="relationship-caption"><button data-milestone="hinge">Our first interaction: Hinge, Jun 24, 2026</button><span>·</span><button data-milestone="dreamwalks">Our first date: Dreamwalks, Jul 08, 2026</button><span>·</span><button data-milestone="dating">We started dating: Hurricane, Aug 23, 2026</button></div></div><div class="collection-grid">${data.lists.map((l,i)=>{const photos=listPhotos(l),index=photos.length?(homePhotoIndices.get(l.id)||0)%photos.length:0,photo=photos[index];return`<article class="collection-card ${photo?'has-photo':''} ${l.kind==='movies'?'is-movie':''}" data-open="${escapeHtml(l.id)}">${photo?`<div class="collection-photo-wrap"><img class="collection-photo" data-home-photo="${escapeHtml(l.id)}" src="${escapeHtml(photo.src)}" alt="" style="object-position:${clampPhotoPosition(photo.position?.x)}% ${clampPhotoPosition(photo.position?.y)}%"><span class="card-count">${String(l.entries.length).padStart(2,'0')} ITEMS</span></div>`:''}<div class="card-top">${photo?'':`<span class="collection-emoji">${l.icon}</span><span class="card-count">${String(l.entries.length).padStart(2,'0')} ITEMS</span>`}</div><h3>${escapeHtml(l.name)}</h3></article>`}).join('')}<button class="collection-card add-card" data-action="new-list"><span class="plus-circle">＋</span><strong>Make a new list</strong><small>Give a new idea a home</small></button></div>`;el.querySelectorAll('[data-open]').forEach(x=>x.onclick=()=>setRoute(x.dataset.open));el.querySelectorAll('[data-action="new-list"]').forEach(x=>x.onclick=openNewList);el.querySelectorAll('[data-milestone]').forEach(x=>x.onclick=()=>openMilestone(x.dataset.milestone));if(data.lists.some(l=>listPhotos(l).length>1))homePhotoTimer=setInterval(()=>{data.lists.forEach(l=>{const photos=listPhotos(l);if(photos.length<2)return;const index=((homePhotoIndices.get(l.id)||0)+1)%photos.length;homePhotoIndices.set(l.id,index);const image=[...el.querySelectorAll('[data-home-photo]')].find(node=>node.dataset.homePhoto===l.id);if(image){image.src=photos[index].src;image.style.objectPosition=`${clampPhotoPosition(photos[index].position.x)}% ${clampPhotoPosition(photos[index].position.y)}%`}})},5000)}
function openMilestone(id){const milestones={hinge:{title:'Our first interaction',detail:'Hinge',date:'Jun 24, 2026'},dreamwalks:{title:'Our first date',detail:'Dreamwalks',date:'Jul 08, 2026'},dating:{title:'We started dating',detail:'Hurricane',date:'Aug 23, 2026'}};const milestone=milestones[id];if(!milestone)return;const memories=data.relationshipMemories?.[id]||[];const media=memories.map((item,i)=>`<div class="relationship-media">${item.type==='video'?`<video src="${escapeHtml(item.src)}" controls preload="metadata"></video>`:`<button class="relationship-media-open" data-view-memory="${i}" aria-label="View photo ${i+1} full size"><img src="${escapeHtml(item.src)}" alt="${milestone.title} memory ${i+1}"></button>`}<button class="photo-delete relationship-delete-media" data-remove-memory="${i}" aria-label="Delete ${item.type==='video'?'video':'photo'} ${i+1}" title="Delete ${item.type==='video'?'video':'photo'}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3m3 0-1 13H7L6 7m4 4v5m4-5v5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></button></div>`).join('');modal(milestone.title,`<p class="milestone-modal-date">${milestone.detail} · ${milestone.date}</p><div class="relationship-media-grid ${memories.length===1?'single-media':''}">${media}<label class="relationship-add-media" title="Add photos or videos" aria-label="Add photos or videos"><span>＋</span><input id="milestoneUpload" type="file" accept="image/*,video/*" multiple hidden></label></div>${memories.length?'':`<p class="no-photos">Add a photo or video from this little beginning ✨</p>`}<p class="modal-hint">Photos are compressed automatically. Videos can be up to 8 MB each.</p>`);document.getElementById('milestoneUpload').onchange=e=>uploadMilestoneMedia(id,e.target.files);document.querySelectorAll('[data-view-memory]').forEach(button=>button.onclick=()=>openPhotoViewer(memories[Number(button.dataset.viewMemory)].src));document.querySelectorAll('[data-remove-memory]').forEach(button=>button.onclick=()=>removeMilestoneMedia(id,Number(button.dataset.removeMemory)));}
async function readMedia(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read file'));reader.readAsDataURL(file)})}
async function uploadMilestoneMedia(id,files){const chosen=[...files].filter(file=>file.type.startsWith('image/')||file.type.startsWith('video/'));if(!chosen.length)return;if(chosen.some(file=>file.type.startsWith('video/')&&file.size>8*1024*1024)){toast('Each video must be 8 MB or smaller');return}const previous=[...(data.relationshipMemories?.[id]||[])];try{data.relationshipMemories=data.relationshipMemories||{};data.relationshipMemories[id]=[...previous,...await Promise.all(chosen.map(async file=>({type:file.type.startsWith('video/')?'video':'image',src:file.type.startsWith('image/')?await compressPhoto(file):await readMedia(file)})))];if(!await save())throw new Error('Could not save');openMilestone(id);toast('Memory saved ✨')}catch{data.relationshipMemories[id]=previous;await save();toast('Could not save this media. Try a smaller file.')}}
async function removeMilestoneMedia(id,index){const previous=[...(data.relationshipMemories?.[id]||[])];data.relationshipMemories[id].splice(index,1);if(!await save()){data.relationshipMemories[id]=previous;toast('Could not remove media');return}openMilestone(id);toast('Memory removed')}
function memoryCards(l){return`<div class="entry-grid">${l.entries.map(e=>{const photos=e.photos||[];const index=photos.length?(cardPhotoIndices.get(e.id)||0)%photos.length:0;const photo=photos[index];const stored=e.photoPositions?.[index]||{x:50,y:50};const position={x:clampPhotoPosition(stored.x),y:clampPhotoPosition(stored.y)};return`<article class="entry-card" data-entry="${escapeHtml(e.id)}"><div class="entry-art">${photo?`<img class="image-cover" src="${escapeHtml(photo)}" alt="" style="object-position:${position.x}% ${position.y}%">`:`<span class="art-emoji">${e.emoji||l.icon}</span><span class="art-label">${escapeHtml(e.place||l.name)}</span>`}</div><div class="entry-info"><h3>${escapeHtml(e.title)}</h3><div class="entry-meta">${e.releaseYear?e.releaseYear+' · ':''}${formatDate(e.date)||'ADD A DATE'}</div></div></article>`}).join('')}<button class="entry-add" data-add><span>＋</span><strong>Add a memory</strong><small>Keep collecting together</small></button></div>`}
function clampPhotoPosition(value){const number=Number(value);return Number.isFinite(number)?Math.min(100,Math.max(0,number)):50}
function movieCategoriesFor(l){if(!Array.isArray(l.movieCategories))l.movieCategories=[...MOVIE_CATEGORIES];return l.movieCategories}
function movieRows(entries,categories){return entries.length?`<div class="movie-list">${entries.map(e=>`<div class="movie-row ${e.watched?'is-watched':''}"><div class="movie-title-group"><div class="movie-poster-thumb">${e.poster?`<img src="${escapeHtml(e.poster)}" alt="">`:'🎬'}</div><button class="movie-title" data-entry="${escapeHtml(e.id)}"><span class="movie-title-main"><span>${escapeHtml(e.title)}</span><span class="movie-rating" aria-label="${Number(e.reviews?.you?.stars)||0} out of 5 stars">${stars(e.reviews?.you?.stars||0)}</span></span><small>${escapeHtml(e.mediaType==='movie'?'Movie':e.mediaType==='tv'?'Series':'Title')}${e.releaseYear?` · ${escapeHtml(e.releaseYear)}`:''}</small></button></div><select class="movie-category-select" data-movie-category-select="${escapeHtml(e.id)}" aria-label="Category for ${escapeHtml(e.title)}"><option value="" ${!e.category?'selected':''}>No category</option>${categories.map(category=>`<option value="${escapeHtml(category)}" ${e.category===category?'selected':''}>${escapeHtml(category)}</option>`).join('')}</select><label class="movie-watched"><input type="checkbox" data-watched="${escapeHtml(e.id)}" ${e.watched?'checked':''}><span>Watched</span></label><label class="movie-date">Date watched<input type="date" data-watch-date="${escapeHtml(e.id)}" value="${escapeHtml(e.date||'')}"></label><button class="movie-delete-title" data-delete-movie="${escapeHtml(e.id)}" title="Delete title" aria-label="Delete ${escapeHtml(e.title)}">×</button></div>`).join('')}</div>`:`<div class="movie-empty">No titles here yet.</div>`}
function movieManager(l){const categories=movieCategoriesFor(l),tabs=['Watched',...categories];if(activeMovieCategory&&!tabs.includes(activeMovieCategory))activeMovieCategory='';const visible=!activeMovieCategory?l.entries:activeMovieCategory==='Watched'?l.entries.filter(e=>e.watched):l.entries.filter(e=>e.category===activeMovieCategory);const unwatched=l.entries.map((entry,index)=>({...entry,_order:index})).filter(entry=>!entry.watched).sort((a,b)=>(Number.isFinite(a.watchOrder)?a.watchOrder:a._order)-(Number.isFinite(b.watchOrder)?b.watchOrder:b._order));return`<div class="movie-manager"><nav class="movie-category-tabs" aria-label="Movie lists">${tabs.map(category=>`<button class="movie-category-tab ${activeMovieCategory===category?'active':''}" data-movie-category="${escapeHtml(category)}">${escapeHtml(category)}${category==='Watched'?` <small>${l.entries.filter(e=>e.watched).length}</small>`:''}</button>`).join('')}<button class="movie-category-add" data-add-movie-category>＋ Add category</button></nav><div class="movie-workspace ${activeMovieCategory?'filtered':'has-queue'}"><section class="movie-category-content"><div class="section-row"><h2>${escapeHtml(activeMovieCategory||l.name)}</h2><div class="movie-section-actions"><small>${visible.length} ${visible.length===1?'TITLE':'TITLES'}</small>${activeMovieCategory==='Watched'?'':`${activeMovieCategory?`<button class="soft-button movie-category-action icon-action" data-edit-category title="Edit category" aria-label="Edit category">✎</button><button class="soft-button movie-category-action icon-action delete-category-action" data-delete-category title="Delete category" aria-label="Delete category">×</button>`:''}<button class="soft-button movie-add-to-category icon-action" data-add-category-title title="Add a title to this category" aria-label="Add a title to this category">＋</button>`}</div></div>${movieRows(visible,categories)}</section>${!activeMovieCategory?`<aside class="watch-queue"><div class="watch-queue-heading"><h2>Up next</h2><small>${unwatched.length} LEFT</small></div><div class="watch-queue-list" role="list">${unwatched.length?unwatched.map((entry,index)=>`<div class="watch-queue-item" role="listitem" draggable="true" tabindex="0" data-queue-item="${escapeHtml(entry.id)}" aria-label="Reorder ${escapeHtml(entry.title)}">${entry.poster?`<img class="watch-queue-poster" src="${escapeHtml(entry.poster)}" alt="" loading="lazy">`:''}<span class="watch-queue-title">${escapeHtml(entry.title)}</span></div>`).join(''):'<p class="watch-queue-empty">Nothing waiting to watch.</p>'}</div></aside>`:''}</div></div>`}

function parkRows(l){return`<div class="parks-list">${l.entries.map(e=>`<div class="park-row ${e.visited?'is-visited':''}" data-entry="${escapeHtml(e.id)}"><div class="park-main"><div class="park-name">${escapeHtml(e.title)}<small>${escapeHtml(e.place||'United States')}</small></div><label class="park-visited"><input type="checkbox" data-visited="${escapeHtml(e.id)}" ${e.visited?'checked':''}><span>Visited</span></label></div><label class="park-date">Date visited<input type="date" data-visit-date="${escapeHtml(e.id)}" value="${escapeHtml(e.date||'')}"></label></div>`).join('')}</div>`}
function seedNationalParks(l){if(l.parkChecklistSeeded)return;const existing=new Set(l.entries.map(e=>e.title.toLowerCase()));for(const [name,place] of NATIONAL_PARKS){if(!existing.has(`${name} national park`.toLowerCase()))l.entries.push({id:`park-${name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`,title:`${name} National Park`,place,visited:false,date:'',emoji:'🏞️',reviews:{you:{stars:0,text:''},chris:{stars:0,text:''}},photos:[]})}l.parkChecklistSeeded=true;save()}
function renderList(){
  const l=listById(activeListId);
  if(!l){setRoute();return}
  if(cardPhotoTimer){clearInterval(cardPhotoTimer);cardPhotoTimer=null}
  const el=document.getElementById('listView');el.classList.remove('hidden');
  const isMovie=l.kind==='movies';const isParkList=l.id==='parks';if(isParkList)seedNationalParks(l);if(isMovie&&dedupeMovieTitles(l))save();
  const entries=isMovie?movieManager(l):l.entries.length?isParkList?parkRows(l):memoryCards(l):`<div class="list-empty"><span>${l.icon}</span><h2 style="font:500 24px var(--serif);color:#555d50;margin:10px 0">A new page, waiting to be filled.</h2><p>Add your first memory whenever you like.</p><button class="primary-button" data-add><span>＋</span>Add the first item</button></div>`;
  el.innerHTML=`<div class="list-heading"><button class="back-button" data-back>←</button><div class="list-heading-copy">${isMovie?`<h1 class="page-title"><button class="movie-home-title" data-movie-home aria-label="Show Up next">${escapeHtml(l.name)}</button></h1>`:`<h1 class="page-title">${escapeHtml(l.name)}</h1>`}</div><div class="list-header-actions"><button class="soft-button list-icon-action" data-edit title="Edit list" aria-label="Edit list">✎</button>${isParkList?'':`<button class="primary-button list-icon-action" data-add title="${isMovie?'Add a title':'Add an item'}" aria-label="${isMovie?'Add a title':'Add an item'}"><span aria-hidden="true">＋</span></button>`}</div></div>${isMovie?'':`<div class="section-row">${isParkList?'<h2>All U.S. national parks</h2>':''}<small>${l.entries.length} ${l.entries.length===1?'ITEM':'ITEMS'}</small></div>`}${entries}`;
  el.querySelector('[data-back]').onclick=()=>setRoute();
  el.querySelector('[data-movie-home]')?.addEventListener('click',()=>{activeMovieCategory='';renderList()});
  el.querySelector('[data-edit]').onclick=()=>openEditList(l);
  el.querySelectorAll('[data-add]').forEach(x=>x.onclick=()=>isMovie?openMovieSearch():openEntryForm(l));
  if(isMovie){
    el.querySelectorAll('[data-movie-category]').forEach(button=>button.onclick=()=>{activeMovieCategory=activeMovieCategory===button.dataset.movieCategory?'':button.dataset.movieCategory;renderList()});
    el.querySelector('[data-add-movie-category]')?.addEventListener('click',()=>openMovieCategoryForm(l));
    el.querySelector('[data-edit-category]')?.addEventListener('click',()=>openEditMovieCategory(l,activeMovieCategory));
    el.querySelector('[data-delete-category]')?.addEventListener('click',()=>confirmDeleteMovieCategory(l,activeMovieCategory));
    el.querySelectorAll('[data-delete-movie]').forEach(button=>button.onclick=event=>{event.stopPropagation();const entry=l.entries.find(item=>item.id===button.dataset.deleteMovie);if(entry)confirmDeleteEntry(l,entry)});
    el.querySelector('[data-add-category-title]')?.addEventListener('click',()=>openMovieSearch(!activeMovieCategory||activeMovieCategory==='Watched'?'':activeMovieCategory));
    el.querySelectorAll('[data-movie-category-select]').forEach(select=>select.onchange=async()=>{const entry=l.entries.find(item=>item.id===select.dataset.movieCategorySelect);if(!entry)return;entry.category=select.value;if(await save())renderList()});
    const queue=el.querySelector('.watch-queue-list');let draggedId=null;
    const moveQueueItem=(fromId,toId)=>{const queueEntries=l.entries.filter(item=>!item.watched).sort((a,b)=>(Number.isFinite(a.watchOrder)?a.watchOrder:l.entries.indexOf(a))-(Number.isFinite(b.watchOrder)?b.watchOrder:l.entries.indexOf(b)));const from=queueEntries.findIndex(item=>item.id===fromId),to=queueEntries.findIndex(item=>item.id===toId);if(from<0||to<0||from===to)return;const [moved]=queueEntries.splice(from,1);queueEntries.splice(to,0,moved);queueEntries.forEach((item,index)=>item.watchOrder=index);save();renderList()};
    queue?.querySelectorAll('[data-queue-item]').forEach(item=>{
      item.draggable=!window.matchMedia('(pointer: coarse)').matches;
      item.ondragstart=event=>{draggedId=item.dataset.queueItem;item.classList.add('is-dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',draggedId)};
      item.ondragend=()=>item.classList.remove('is-dragging');
      item.ondragover=event=>event.preventDefault();
      item.ondrop=event=>{event.preventDefault();moveQueueItem(draggedId||event.dataTransfer.getData('text/plain'),item.dataset.queueItem)};
      let pressTimer=null,touchDragging=false,touchTargetId=null;
      item.addEventListener('touchstart',()=>{pressTimer=setTimeout(()=>{touchDragging=true;item.classList.add('is-touch-dragging')},420)},{passive:true});
      item.addEventListener('touchmove',event=>{if(!touchDragging)return;event.preventDefault();const touch=event.touches[0],target=document.elementFromPoint(touch.clientX,touch.clientY)?.closest('[data-queue-item]');queue.querySelectorAll('.is-drop-target').forEach(node=>node.classList.remove('is-drop-target'));if(target){touchTargetId=target.dataset.queueItem;target.classList.add('is-drop-target')}},{passive:false});
      const finishTouchDrag=()=>{clearTimeout(pressTimer);if(touchDragging){item.classList.remove('is-touch-dragging');queue.querySelectorAll('.is-drop-target').forEach(node=>node.classList.remove('is-drop-target'));if(touchTargetId&&touchTargetId!==item.dataset.queueItem)moveQueueItem(item.dataset.queueItem,touchTargetId)}touchDragging=false;touchTargetId=null};
      item.addEventListener('touchend',finishTouchDrag);item.addEventListener('touchcancel',finishTouchDrag);
      item.onkeydown=event=>{if(!['ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();const sorted=l.entries.filter(entry=>!entry.watched).sort((a,b)=>(Number.isFinite(a.watchOrder)?a.watchOrder:l.entries.indexOf(a))-(Number.isFinite(b.watchOrder)?b.watchOrder:l.entries.indexOf(b)));const index=sorted.findIndex(entry=>entry.id===item.dataset.queueItem),target=index+(event.key==='ArrowUp'?-1:1);if(target>=0&&target<sorted.length)moveQueueItem(item.dataset.queueItem,sorted[target].id)};
    });
  }
  el.querySelectorAll('[data-entry]').forEach(x=>x.onclick=event=>{if(event.target.closest('input,label,select'))return;setRoute(l.id,x.dataset.entry)});
  el.querySelectorAll('[data-watched]').forEach(input=>input.onchange=()=>{const entry=l.entries.find(x=>x.id===input.dataset.watched);if(!entry)return;entry.watched=input.checked;save();if(isMovie)renderList();else input.closest('.movie-row').classList.toggle('is-watched',entry.watched)});
  el.querySelectorAll('[data-watch-date]').forEach(input=>input.onchange=()=>{const entry=l.entries.find(x=>x.id===input.dataset.watchDate);if(entry){entry.date=input.value;save()}});
  el.querySelectorAll('[data-visited]').forEach(input=>input.onchange=()=>{const entry=l.entries.find(x=>x.id===input.dataset.visited);if(entry){entry.visited=input.checked;input.closest('.park-row').classList.toggle('is-visited',entry.visited);save()}});
  el.querySelectorAll('[data-visit-date]').forEach(input=>input.onchange=()=>{const entry=l.entries.find(x=>x.id===input.dataset.visitDate);if(entry){entry.date=input.value;save()}});

  const rotating=l.entries.filter(entry=>(entry.photos||[]).length>1);if(!isMovie&&!isParkList&&rotating.length)cardPhotoTimer=setInterval(()=>{rotating.forEach(entry=>{const count=entry.photos.length;cardPhotoIndices.set(entry.id,((cardPhotoIndices.get(entry.id)||0)+1)%count)});renderList()},5000);
}
function renderDetail(){if(photoTimer){clearInterval(photoTimer);photoTimer=null}const l=listById(activeListId),e=entryById();if(!l||!e){setRoute(activeListId);return}const el=document.getElementById('detailView');el.classList.remove('hidden');el.innerHTML=`<div class="detail-heading"><button class="back-button" data-back>←</button><div><div class="eyebrow">${escapeHtml(l.name.toUpperCase())}</div><h1 class="page-title">${escapeHtml(e.title)}</h1><div class="detail-date">${formatDate(e.date)||'A MEMORY TO REMEMBER'}</div></div><div class="detail-actions"><button class="soft-button" data-edit>✎ Edit</button><button class="soft-button" data-delete>Delete</button></div></div><div class="carousel"><div class="carousel-tabs"><button class="carousel-tab ${activeSlide===0?'active':''}" data-slide="0">01 &nbsp; The day</button><button class="carousel-tab ${activeSlide===1?'active':''}" data-slide="1">02 &nbsp; Our reviews</button><button class="carousel-tab ${activeSlide===2?'active':''}" data-slide="2">03 &nbsp; Photos</button></div><div class="slide">${activeSlide===0?posterSlide(e):activeSlide===1?reviewsSlide(e):photosSlide(e,activePhotoIndex)}</div><div class="slide-nav"><button class="slide-arrow" data-prev>←</button><button class="slide-arrow" data-next>→</button></div></div>`;el.querySelector('[data-back]').onclick=()=>setRoute(l.id);el.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEntryForm(l,e));el.querySelector('[data-delete]').onclick=()=>confirmDeleteEntry(l,e);el.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>{activeSlide=Number(b.dataset.slide);renderDetail()});el.querySelector('[data-prev]').onclick=()=>{activeSlide=(activeSlide+2)%3;renderDetail()};el.querySelector('[data-next]').onclick=()=>{activeSlide=(activeSlide+1)%3;renderDetail()};el.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>openReview(e,b.dataset.review));el.querySelector('[data-upload]')?.addEventListener('change',ev=>uploadPhotos(ev.target.files));el.querySelector('[data-photo-view]')?.addEventListener('click',()=>openPhotoViewer(e.photos[activePhotoIndex]));el.querySelector('[data-photo-prev]')?.addEventListener('click',()=>{activePhotoIndex=(activePhotoIndex+e.photos.length-1)%e.photos.length;renderDetail()});el.querySelector('[data-photo-next]')?.addEventListener('click',()=>{activePhotoIndex=(activePhotoIndex+1)%e.photos.length;renderDetail()});el.querySelectorAll('[data-photo-select]').forEach(b=>b.onclick=()=>{activePhotoIndex=Number(b.dataset.photoSelect);renderDetail()});el.querySelectorAll('[data-delete-photo]').forEach(b=>b.onclick=()=>confirmDeletePhoto(e,Number(b.dataset.deletePhoto)));if(activeSlide===2&&(e.photos||[]).length>1)photoTimer=setInterval(()=>{activePhotoIndex=(activePhotoIndex+1)%e.photos.length;renderDetail()},5000)}
function posterSlide(e){const image=e.poster||e.photos?.[0];return`<div class="slide-poster"><div class="poster-placeholder">${image?`<img src="${escapeHtml(image)}" alt="${escapeHtml(e.title)}">`:`<span>${e.emoji||'✨'}</span>`}</div><div class="poster-copy"><div class="date-line">${formatDate(e.date)||'A DAY TO REMEMBER'}</div><h2>${escapeHtml(e.title)}</h2><p>${escapeHtml(e.place||'Add a little note about where you went and what made the day special.')}</p><button class="soft-button" data-edit>✎ Edit the details</button></div></div>`}
function openPhotoViewer(src){modal('Photo',`<div class="photo-viewer"><img src="${escapeHtml(src)}" alt="Full-size memory photo"></div>`)}
function photosSlide(e,index=0){const photos=e.photos||[];return`<div class="photos-panel"><div class="section-kicker">LITTLE MOMENTS, KEPT FOREVER</div>${photos.length?`<div class="photo-presentation"><button class="photo-current" data-photo-view aria-label="Open photo full size"><img src="${escapeHtml(photos[index]||photos[0])}" alt="Photo ${index+1} of ${photos.length}"></button>${photos.length>1?`<div class="photo-controls"><button class="soft-button" data-photo-prev aria-label="Previous photo">←</button><span>Photo ${index+1} of ${photos.length} · changes every 5 seconds</span><button class="soft-button" data-photo-next aria-label="Next photo">→</button></div>`:''}</div><div class="photo-grid">${photos.map((photo,i)=>`<div class="photo-thumb-wrap"><button class="photo-tile photo-thumb ${i===index?'selected':''}" data-photo-select="${i}" aria-label="Show photo ${i+1}"><img src="${escapeHtml(photo)}" alt="Memory photo ${i+1}"></button><button class="photo-delete" data-delete-photo="${i}" aria-label="Delete photo ${i+1}" title="Delete photo">×</button></div>`).join('')}<label class="photo-tile upload-tile"><span>＋</span>Add photos<input data-upload type="file" accept="image/*" multiple hidden></label></div>`:`<div class="photo-grid"><label class="photo-tile upload-tile"><span>＋</span>Add photos<input data-upload type="file" accept="image/*" multiple hidden></label></div><div class="no-photos">Every good memory deserves a photo. Add one when you’re ready ✨</div>`}</div>`}
function confirmDeletePhoto(e,index){const photo=e.photos?.[index];if(!photo)return;modal('Delete this photo?',`<p class="subhead">This photo will be removed from this memory and the shared list.</p><div class="modal-actions"><button class="cancel-button" data-cancel>Keep photo</button><button class="primary-button" style="background:#a94e40" data-confirm>Delete photo</button></div>`);document.querySelector('[data-cancel]').onclick=()=>{closeModal();renderDetail()};document.querySelector('[data-confirm]').onclick=async()=>{closeModal();const oldPosition=e.photoPositions?.[index];e.photos.splice(index,1);if(e.photoPositions)e.photoPositions.splice(index,1);const cardIndex=cardPhotoIndices.get(e.id)||0;if(index<cardIndex)cardPhotoIndices.set(e.id,cardIndex-1);else if(cardIndex>=e.photos.length)cardPhotoIndices.set(e.id,0);if(activePhotoIndex>=e.photos.length)activePhotoIndex=Math.max(0,e.photos.length-1);else if(index<activePhotoIndex)activePhotoIndex--;if(await save()){renderDetail();toast('Photo deleted')}else{e.photos.splice(index,0,photo);if(e.photoPositions)e.photoPositions.splice(index,0,oldPosition);await save();activePhotoIndex=Math.min(index,e.photos.length-1);renderDetail();toast('Could not delete photo. Check your connection and try again.')}}}
function reviewsSlide(e){return`<div class="review-stack">${['you','chris'].map((who,i)=>{const r=e.reviews?.[who]||{stars:0,text:''};return`<div class="review-card"><span class="review-avatar">${i?'C':'Y'}</span><div><div class="review-name">${i?'Chris':'You'}</div><div class="review-stars">${stars(r.stars)}</div><div class="review-text ${r.text?'':'review-empty'}">${r.text?escapeHtml(r.text):'No review yet — add your thoughts.'}</div><button class="soft-button" style="margin-top:11px;padding:7px 10px" data-review="${who}">✎ ${r.text?'Edit review':'Write a review'}</button></div></div>`}).join('')}</div>`}
function formatDate(s){if(!s)return'';const d=new Date(s+'T12:00:00');return Number.isNaN(d.getTime())?s:d.toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}).toUpperCase()}function stars(n){return '★'.repeat(Math.max(0,Math.min(5,Number(n)||0)))+'☆'.repeat(5-Math.max(0,Math.min(5,Number(n)||0)))}function uid(){return Math.random().toString(36).slice(2,10)}
function modal(title,content){const root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="modal-close" aria-label="Close">×</button></div>${content}</div></div>`;root.querySelector('.modal-close').onclick=closeModal;root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};return root.querySelector('.modal')}
function closeModal(){document.getElementById('modalRoot').innerHTML=''}function openNewList(){modal('A new little list',`<form id="newListForm"><div class="field"><label>List name</label><input name="name" placeholder="Weekend adventures" required maxlength="40"></div><div class="field"><label>A little description</label><input name="description" placeholder="Things we want to do together"></div><div class="field-row"><div class="field"><label>Choose an icon</label><select name="icon"><option>✨</option><option>🎪</option><option>🎬</option><option>🏞️</option><option>🍁</option><option>🍜</option><option>✈️</option><option>📚</option><option>🌱</option></select></div><div class="field"><label>List type</label><select name="kind"><option value="notes">General list</option><option value="festival">Events & memories</option><option value="movies">Movies & series</option></select></div></div><div class="modal-actions"><button type="button" class="cancel-button" data-cancel>Cancel</button><button class="primary-button">Create list</button></div></form>`);const f=document.getElementById('newListForm');f.onsubmit=e=>{e.preventDefault();const fd=new FormData(f),name=fd.get('name').trim();data.lists.push({id:uid(),name,icon:fd.get('icon'),description:fd.get('description').trim()||'A collection of things we love.',kind:fd.get('kind'),entries:[]});save();closeModal();render();toast('Your new list is ready ✨')};f.querySelector('[data-cancel]').onclick=closeModal}
function openEditList(l){modal('Edit this list',`<form id="editListForm"><div class="field"><label>List name</label><input name="name" value="${escapeHtml(l.name)}" required maxlength="40"></div><div class="field"><label>Description</label><input name="description" value="${escapeHtml(l.description||'')}"></div><div class="field-row"><div class="field"><label>Icon</label><select name="icon">${['✨','🎪','🎬','🏞️','🍁','🍜','✈️','📚','🌱'].map(i=>`<option ${l.icon===i?'selected':''}>${i}</option>`).join('')}</select></div><div class="field"><label>List type</label><select name="kind"><option value="notes" ${l.kind==='notes'?'selected':''}>General list</option><option value="festival" ${l.kind==='festival'?'selected':''}>Events & memories</option><option value="movies" ${l.kind==='movies'?'selected':''}>Movies & series</option></select></div></div><div class="modal-actions"><button type="button" class="cancel-button" data-delete-list style="margin-right:auto;color:#a94e40">Delete list</button><button type="button" class="cancel-button" data-cancel>Cancel</button><button class="primary-button">Save changes</button></div></form>`);const f=document.getElementById('editListForm');f.onsubmit=e=>{e.preventDefault();const fd=new FormData(f);l.name=fd.get('name').trim();l.description=fd.get('description').trim();l.icon=fd.get('icon');l.kind=fd.get('kind');save();closeModal();render();toast('List updated')};f.querySelector('[data-cancel]').onclick=closeModal;f.querySelector('[data-delete-list]').onclick=()=>confirmDeleteList(l)}
function confirmDeleteList(l){modal('Delete this list?',`<p class="subhead">“${escapeHtml(l.name)}” and all ${l.entries.length} ${l.entries.length===1?'item':'items'}, including their reviews and photos, will be permanently removed.</p><div class="modal-actions"><button class="cancel-button" data-cancel>Keep list</button><button class="primary-button" style="background:#a94e40" data-confirm>Delete list</button></div>`);document.querySelector('[data-cancel]').onclick=()=>openEditList(l);document.querySelector('[data-confirm]').onclick=()=>{data.lists=data.lists.filter(x=>x.id!==l.id);activeListId=null;activeEntryId=null;save();closeModal();setRoute();toast('List deleted')}}
function openEntryForm(l,e=null,category=''){const edit=!!e;e=e||{title:'',date:'',place:'',emoji:l.icon,reviews:{you:{stars:0,text:''},chris:{stars:0,text:''}},photos:[]};modal(edit?'Edit this memory':'Add to '+escapeHtml(l.name),`<form id="entryForm"><div class="field"><label>Title</label><input name="title" value="${escapeHtml(e.title)}" placeholder="A lovely day out" required maxlength="80"></div><div class="field-row"><div class="field"><label>${l.kind==='movies'?'Date watched':'Date'}</label><input name="date" type="date" value="${escapeHtml(e.date||'')}"></div><div class="field"><label>Little icon</label><select name="emoji">${['✨','🎪','🎈','🍂','🎸','🌱','🎟️','🏞️','🍁','❤️','🌙','🎉'].map(i=>`<option ${e.emoji===i?'selected':''}>${i}</option>`).join('')}</select></div></div><div class="field"><label>Place or a little note</label><input name="place" value="${escapeHtml(e.place||'')}" placeholder="The music, the food, how it felt..."></div><p class="modal-hint">You can add both reviews and photos from the memory page.</p><div class="modal-actions">${edit?'<button type="button" class="cancel-button" data-delete>Delete</button>':''}<button type="button" class="cancel-button" data-cancel>Cancel</button><button class="primary-button">${edit?'Save changes':'Add memory'}</button></div></form>`);const f=document.getElementById('entryForm');f.onsubmit=ev=>{ev.preventDefault();const fd=new FormData(f),title=fd.get('title').trim();if(duplicateTitle(l,title,edit?e.id:null)){toast('That title is already in this list');return}if(edit){e.title=title;e.date=fd.get('date');e.place=fd.get('place').trim();e.emoji=fd.get('emoji')}else l.entries.push({id:uid(),title,date:fd.get('date'),place:fd.get('place').trim(),emoji:fd.get('emoji'),reviews:{you:{stars:0,text:''},chris:{stars:0,text:''}},photos:[],...(l.kind==='movies'?{watched:false,mediaType:'movie',category}:{})});save();closeModal();render();toast(edit?'Memory updated':'Added to your list ✨')};f.querySelector('[data-cancel]').onclick=closeModal;f.querySelector('[data-delete]')?.addEventListener('click',()=>{closeModal();confirmDeleteEntry(l,e)})}
function confirmDeleteEntry(l,e){modal('Delete this memory?',`<p class="subhead">“${escapeHtml(e.title)}” and its reviews and photos will be removed.</p><div class="modal-actions"><button class="cancel-button" data-cancel>Keep it</button><button class="primary-button" style="background:#a94e40" data-confirm>Delete memory</button></div>`);document.querySelector('[data-cancel]').onclick=closeModal;document.querySelector('[data-confirm]').onclick=()=>{l.entries=l.entries.filter(x=>x.id!==e.id);save();closeModal();setRoute(l.id);toast('Memory deleted')}}
function openReview(e,who){const r=e.reviews?.[who]||{stars:0,text:''};modal((who==='you'?'Your':'Chris’s')+' review',`<form id="reviewForm"><div class="field"><label>Your rating</label><div class="stars-select">${[1,2,3,4,5].map(i=>`<button type="button" data-star="${i}" class="${i<=r.stars?'selected':''}">★</button>`).join('')}</div><input name="stars" type="hidden" value="${r.stars}"></div><div class="field"><label>A few words about it</label><textarea name="text" placeholder="What did you love? What will you remember?">${escapeHtml(r.text)}</textarea></div><div class="modal-actions"><button type="button" class="cancel-button" data-cancel>Cancel</button><button class="primary-button">Save review</button></div></form>`);const f=document.getElementById('reviewForm');f.querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>{f.elements.stars.value=b.dataset.star;f.querySelectorAll('[data-star]').forEach(x=>x.classList.toggle('selected',Number(x.dataset.star)<=Number(b.dataset.star)))});f.onsubmit=ev=>{ev.preventDefault();e.reviews=e.reviews||{};e.reviews[who]={stars:Number(f.elements.stars.value),text:f.elements.text.value.trim()};save();closeModal();renderDetail();toast('Review saved ✨')};f.querySelector('[data-cancel]').onclick=closeModal}
function openMovieCategoryForm(l){modal('Add a movie category',`<form id="movieCategoryForm"><div class="field"><label>Category name</label><input name="name" maxlength="32" placeholder="e.g. Cozy mysteries" required></div><div class="modal-actions"><button type="button" class="cancel-button" data-cancel>Cancel</button><button class="primary-button">Create category</button></div></form>`);const form=document.getElementById('movieCategoryForm');form.querySelector('[data-cancel]').onclick=closeModal;form.onsubmit=async event=>{event.preventDefault();const name=new FormData(form).get('name').trim();const categories=movieCategoriesFor(l);if(!name){toast('Enter a category name');return}if(categories.some(category=>category.toLowerCase()===name.toLowerCase())){toast('That category already exists');return}categories.push(name);activeMovieCategory=name;if(await save()){closeModal();renderList();toast('Category created')}}}
function openEditMovieCategory(l,oldName){modal('Edit category',`<form id="editMovieCategoryForm"><div class="field"><label>Category name</label><input name="name" maxlength="32" value="${escapeHtml(oldName)}" required></div><div class="modal-actions"><button type="button" class="cancel-button" data-cancel>Cancel</button><button class="primary-button">Save category</button></div></form>`);const form=document.getElementById('editMovieCategoryForm');form.querySelector('[data-cancel]').onclick=closeModal;form.onsubmit=async event=>{event.preventDefault();const newName=new FormData(form).get('name').trim(),categories=movieCategoriesFor(l);if(!newName){toast('Enter a category name');return}if(categories.some(category=>category!==oldName&&category.toLowerCase()===newName.toLowerCase())){toast('That category already exists');return}const index=categories.indexOf(oldName);if(index<0)return;categories[index]=newName;l.entries.forEach(entry=>{if(entry.category===oldName)entry.category=newName});activeMovieCategory=newName;if(await save()){closeModal();renderList();toast('Category updated')}else toast('Could not save the category. Try again.')}}
function confirmDeleteMovieCategory(l,name){modal('Delete this category?',`<p class="subhead">“${escapeHtml(name)}” will be removed. Titles in this category will stay in your collection without a category.</p><div class="modal-actions"><button class="cancel-button" data-cancel>Keep category</button><button class="primary-button" data-confirm>Delete category</button></div>`);document.querySelector('[data-cancel]').onclick=closeModal;document.querySelector('[data-confirm]').onclick=async()=>{const categories=movieCategoriesFor(l),index=categories.indexOf(name);if(index<0){closeModal();return}categories.splice(index,1);const changed=l.entries.filter(entry=>entry.category===name);changed.forEach(entry=>entry.category='');activeMovieCategory='';if(await save()){closeModal();renderList();toast('Category deleted')}else{categories.splice(index,0,name);changed.forEach(entry=>entry.category=name);activeMovieCategory=name;toast('Could not delete the category. Try again.')}}}
function openMovieSearch(category=''){const l=listById(activeListId);const isLocal=['localhost','127.0.0.1'].includes(location.hostname);const localKeyField=isLocal?`<div class="field"><label>Local TMDB API key (optional)</label><div class="movie-search-box"><input id="tmdbKeyInput" type="password" placeholder="Paste your TMDB API key" value="${escapeHtml(localStorage.getItem('tmdb-api-key')||'')}"><button class="soft-button" id="saveTmdbKey">Save key</button></div></div>`:'';const helpText=isLocal?'Search movies with your local TMDB key. Series search works via TVmaze.':'Movie search uses the site’s secure TMDB connection. Series search works via TVmaze.';modal('Find a movie or series',`<div class="field"><label>Search movies & series</label><div class="movie-search-box"><input id="movieQuery" placeholder="Try a title, like Past Lives" autocomplete="off"><button class="primary-button" id="movieSearchButton">Search</button></div></div><div class="modal-hint">${helpText}</div>${localKeyField}<div class="search-results" id="movieResults"></div><div class="modal-actions"><button class="cancel-button" id="manualMovie">Add a title manually</button></div>`);const inp=document.getElementById('movieQuery');document.getElementById('movieSearchButton').onclick=()=>searchMovies(inp.value,category);inp.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();searchMovies(inp.value,category)}};const saveKeyButton=document.getElementById('saveTmdbKey');if(saveKeyButton)saveKeyButton.onclick=()=>{const key=document.getElementById('tmdbKeyInput').value.trim();if(key){localStorage.setItem('tmdb-api-key',key);window.TMDB_API_KEY=key;toast('TMDB key saved in this browser')}else{localStorage.removeItem('tmdb-api-key');window.TMDB_API_KEY='';toast('TMDB key removed')}};document.getElementById('manualMovie').onclick=()=>{closeModal();openEntryForm(l,null,category)};inp.focus()}
async function searchMovies(q,category=''){const box=document.getElementById('movieResults');if(!q.trim())return;const key=localStorage.getItem('tmdb-api-key')||window.TMDB_API_KEY||'';const isLocal=['localhost','127.0.0.1'].includes(location.hostname);box.innerHTML='<p class="modal-hint">Searching…</p>';try{let results,makePoster;if(!isLocal||key){const url=!isLocal?`/api/tmdb-search?query=${encodeURIComponent(q)}`:`https://api.themoviedb.org/3/search/multi?api_key=${encodeURIComponent(key)}&query=${encodeURIComponent(q)}&include_adult=false`;const res=await fetch(url);if(!res.ok){if(res.status===503)throw new Error('TMDB is not configured on Vercel yet. Add TMDB_API_KEY in Project Settings → Environment Variables, then redeploy.');throw new Error('TMDB search failed. Check the API key and try again.')}const json=await res.json();results=(json.results||[]).filter(x=>['movie','tv'].includes(x.media_type));makePoster=x=>x.poster_path?`https://image.tmdb.org/t/p/w500${x.poster_path}`:''}else{const res=await fetch(`https://api.tvmaze.com/search/shows?q=${encodeURIComponent(q)}`);if(!res.ok)throw new Error('Could not reach TVmaze. Try again.');const json=await res.json();results=json.map(item=>({...item.show,media_type:'tv',name:item.show.name,first_air_date:item.show.premiered,poster_path:item.show.image?.medium,source:'tvmaze'}));makePoster=x=>x.poster_path||''}box.innerHTML=results.length?results.slice(0,12).map((x,i)=>`<div class="movie-result" data-movie="${i}"><div class="movie-thumb">${makePoster(x)?`<img class="image-cover" src="${escapeHtml(makePoster(x))}" alt="">`:'No poster'}</div><div><b>${escapeHtml(x.title||x.name)}</b><small>${x.media_type==='movie'?'Movie':'Series'} · ${(x.release_date||x.first_air_date||'').slice(0,4)}${x.source==='tvmaze'?' · TVmaze':''}</small></div></div>`).join(''):'<p class="modal-hint">No titles found. Try another search.</p>';box.querySelectorAll('[data-movie]').forEach(el=>el.onclick=()=>{const x=results[Number(el.dataset.movie)],movieList=listById(activeListId),title=x.title||x.name;if(duplicateTitle(movieList,title)){toast('That title is already in Movies & Series');return}movieList.entries.push({id:uid(),title,releaseYear:(x.release_date||x.first_air_date||'').slice(0,4),poster:makePoster(x),mediaType:x.media_type,watched:false,category,source:x.source,sourceUrl:x.url,emoji:'🎬',date:'',place:'',reviews:{you:{stars:0,text:''},chris:{stars:0,text:''}},photos:[]});save();closeModal();render();toast('Added to your watchlist 🎬')})}catch(e){box.innerHTML=`<p class="modal-hint">${escapeHtml(e.message||'Could not reach the search service. Check your connection and try again.')}</p>`}}
async function compressPhoto(file){const bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/bitmap.width,1600/bitmap.height);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise((resolve,reject)=>canvas.toBlob(result=>result?resolve(result):reject(new Error('Could not process image')), 'image/jpeg',0.76));return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read image'));reader.readAsDataURL(blob)})}
async function uploadPhotos(files){const e=entryById();if(!e)return;const images=[...files].filter(f=>f.type.startsWith('image/'));if(!images.length)return;const existing=[...(e.photos||[])];try{e.photos=e.photos||[];for(const file of images)e.photos.push(await compressPhoto(file));const saved=await save();if(!saved)throw new Error('Could not sync photos');activeSlide=2;activePhotoIndex=0;renderDetail();toast(`${images.length===1?'Photo':'Photos'} saved ✨`)}catch{e.photos=existing;await save();toast('Photo could not be saved. Check your connection or try a smaller image.') }}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)}
document.getElementById('sidebarAdd').onclick=openNewList;document.getElementById('homeBrand')?.addEventListener('click',e=>{e.preventDefault();setRoute()});document.getElementById('searchToggle').onclick=()=>{document.querySelector('.all-search')?.remove();const box=document.createElement('div');box.className='all-search';box.innerHTML='<input placeholder="Find a list or memory…" autofocus>';document.body.append(box);const inp=box.querySelector('input');inp.focus();inp.oninput=()=>{const q=inp.value.toLowerCase();if(!q)return;const l=data.lists.find(x=>x.name.toLowerCase().includes(q)||x.entries.some(e=>e.title.toLowerCase().includes(q)));if(l)setRoute(l.id)};setTimeout(()=>document.addEventListener('click',function dismiss(ev){if(!box.contains(ev.target)&&ev.target.id!=='searchToggle'){box.remove();document.removeEventListener('click',dismiss)}}),0)};
render();
